/**
 * Database schema. Mirrors `packages/backend/convex/schema.ts`. Auth tables:
 * `./auth-schema`.
 *
 * Conventions:
 * - Ids are UUIDv7 generated by Postgres (`uuidv7()`), so they sort by creation.
 * - Every user-owned row has `user_id`; ownership is checked in the API, never
 *   taken from the client. It references `users` with ON DELETE RESTRICT: there
 *   is no account deletion, and deleting a user must never wipe finance data.
 * - Money is in minor units, `bigint` read as a JS number.
 * - Calendar dates (`"2026-04-05"`) are `date` read as strings; instants are
 *   `timestamptz`. `created_at` replaces Convex's implicit `_creationTime`.
 *   Unlike Convex's string compare, a `date` bound must be a real day: code
 *   that builds `${month}-31` as a month's end must compute the last day.
 * - Closed sets of values are Postgres enums.
 * - Foreign keys between domain rows are composite, `(x_id, user_id)
 *   REFERENCES t (id, user_id)` ({@link ownedBy}): Postgres refuses a row
 *   that points at another user's row.
 * - Foreign keys between domain rows are `DEFERRABLE INITIALLY DEFERRED`
 *   (migrations 0001 and 0003, Drizzle can't declare it): they are checked at commit, so
 *   code ported from Convex may write and delete linked rows in any order
 *   within one transaction, and an import may load tables in any order. The
 *   three `ON DELETE SET NULL` keys reproduce what Convex did with a dangling
 *   id (see each one).
 * - Before 2026-11-11 Convex let an account or transaction be deleted while
 *   other rows still referenced it, and its code tolerates the missing row
 *   (`if (account)`, "Unknown" account, `unknown_currency` in reports). Those
 *   references are nullable here: null means "deleted before the guards"; the
 *   import writes null for a dangling id. New ones can't dangle (the keys).
 *   Convex never checked ownership either: the import also writes null for a
 *   nullable reference to another user's row, which the composite keys refuse.
 */
import { sql } from "drizzle-orm";
import {
  type PgColumn,
  bigint,
  boolean,
  date,
  doublePrecision,
  foreignKey,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

import { users } from "./auth-schema";

export * from "./auth-schema";

/* -------------------------------------------------------------------------- */
/*  Column helpers                                                            */
/* -------------------------------------------------------------------------- */

const id = () => uuid("id").primaryKey().default(sql`uuidv7()`);
/** Owner. */
const userId = () =>
  uuid("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "restrict" });
const createdAt = () => timestamp("created_at", { withTimezone: true, mode: "date" }).notNull().defaultNow();
/** Minor units (value × 100). */
const money = (name: string) => bigint(name, { mode: "number" });
/** Calendar date as `YYYY-MM-DD`. */
const day = (name: string) => date(name, { mode: "string" });
const instant = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });
/** UTC calendar date of the insert, as Convex's `new Date().toISOString().slice(0, 10)`. */
const createdOn = () => day("created_on").notNull().default(sql`(now() at time zone 'utc')::date`);

/** `UNIQUE (id, user_id)`: the target of {@link ownedBy} keys. */
const ownerKey = (table: string, t: { id: PgColumn; userId: PgColumn }) =>
  unique(`${table}_id_user_id_key`).on(t.id, t.userId);

/**
 * `(column, user_id) REFERENCES target (id, user_id)`: a row can only point at
 * a row of the same user. MATCH SIMPLE, so a null `column` passes. Named
 * `<table>_<column>_fk` (Drizzle's default name passes Postgres's 63 chars).
 * Migration 0003 makes these DEFERRABLE INITIALLY DEFERRED and writes
 * `onDelete: "set null"` as `SET NULL (column)`, so `user_id` is never nulled.
 */
const ownedBy = (
  table: string,
  column: PgColumn,
  t: { userId: PgColumn },
  target: { id: PgColumn; userId: PgColumn },
) => foreignKey({ name: `${table}_${column.name}_fk`, columns: [column, t.userId], foreignColumns: [target.id, target.userId] });

/* -------------------------------------------------------------------------- */
/*  Enums                                                                     */
/* -------------------------------------------------------------------------- */

export const accountType = pgEnum("account_type", [
  "bank",
  "savings",
  "credit_card",
  "cash",
  "e_wallet",
  "loan",
  "investment",
]);
export const categoryType = pgEnum("category_type", ["income", "expense"]);
export const transactionType = pgEnum("transaction_type", ["income", "expense", "adjustment", "transfer"]);
export const debtType = pgEnum("debt_type", [
  "credit_card",
  "loan",
  "mortgage",
  "student_loan",
  "personal_loan",
  "other",
]);
/** Chat channels a user can link. Add a value to support another one. */
export const channel = pgEnum("channel", ["telegram"]);
export const channelScope = pgEnum("channel_scope", ["finance:read", "finance:write"]);
export const agentEventStatus = pgEnum("agent_event_status", ["received", "processing", "done", "failed"]);
export const agentMessageRole = pgEnum("agent_message_role", ["user", "assistant", "tool", "system"]);
export const agentActionStatus = pgEnum("agent_action_status", [
  "pending",
  "confirmed",
  "cancelled",
  "expired",
  "executed",
  "failed",
]);

/* -------------------------------------------------------------------------- */
/*  User profile (settings, onboarding state)                                 */
/* -------------------------------------------------------------------------- */

export const userProfiles = pgTable(
  "user_profiles",
  {
    id: id(),
    userId: userId(),
    name: text("name"),
    /** ISO 4217 code, e.g. "USD". */
    baseCurrency: text("base_currency").notNull(),
    onboardingCompleted: boolean("onboarding_completed").notNull().default(false),
    createdAt: createdAt(),
  },
  // Convex read it with `.unique()`: one profile per user.
  (t) => [uniqueIndex("user_profiles_user_id_key").on(t.userId)],
);

/* -------------------------------------------------------------------------- */
/*  Financial accounts                                                        */
/* -------------------------------------------------------------------------- */

export const accounts = pgTable(
  "accounts",
  {
    id: id(),
    userId: userId(),
    name: text("name").notNull(),
    type: accountType("type").notNull(),
    /** Stored, updated in place by transaction, transfer, goal and debt writes. */
    balance: money("balance").notNull(),
    /** ISO 4217 code. */
    currency: text("currency").notNull(),
    /** Visual theme id, e.g. "laranja". */
    theme: text("theme"),
    /** Lucide icon name override. */
    icon: text("icon"),
    description: text("description"),
    /** Soft delete: hidden from lists by default. */
    archived: boolean("archived").notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index("accounts_user_id_idx").on(t.userId, t.createdAt), ownerKey("accounts", t)],
);

/* -------------------------------------------------------------------------- */
/*  Categories and subcategories (one level deep)                             */
/* -------------------------------------------------------------------------- */

export const categories = pgTable(
  "categories",
  {
    id: id(),
    userId: userId(),
    name: text("name").notNull(),
    type: categoryType("type").notNull(),
    /** Lucide icon name. */
    icon: text("icon"),
    /** Hex color, e.g. "#9FE870". */
    color: text("color"),
    /** Seeded by the system. */
    isDefault: boolean("is_default").notNull().default(false),
    /** Soft delete: hidden from pickers, kept on historical records. */
    archived: boolean("archived").notNull().default(false),
    /** User-defined order within the type group. */
    sortOrder: integer("sort_order"),
    createdAt: createdAt(),
  },
  (t) => [
    index("categories_user_id_idx").on(t.userId, t.createdAt),
    index("categories_user_id_type_idx").on(t.userId, t.type, t.createdAt),
    ownerKey("categories", t),
  ],
);

export const subcategories = pgTable(
  "subcategories",
  {
    id: id(),
    userId: userId(),
    /** Deferred FK. The category delete removes its subcategories in the same transaction. */
    categoryId: uuid("category_id").notNull(),
    name: text("name").notNull(),
    archived: boolean("archived").notNull().default(false),
    sortOrder: integer("sort_order").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index("subcategories_category_id_idx").on(t.categoryId, t.createdAt),
    index("subcategories_user_id_idx").on(t.userId, t.createdAt),
    ownerKey("subcategories", t),
    ownedBy("subcategories", t.categoryId, t, categories),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Transactions                                                              */
/* -------------------------------------------------------------------------- */

export const transactions = pgTable(
  "transactions",
  {
    id: id(),
    userId: userId(),
    type: transactionType("type").notNull(),
    /** Minor units. Positive, except adjustments, which are signed. */
    amount: money("amount").notNull(),
    /**
     * Deferred FK: an account can only be deleted once nothing references it.
     * Null only on legacy rows whose account Convex deleted (see the header).
     */
    accountId: uuid("account_id"),
    /**
     * Categories and subcategories can be deleted while transactions use
     * them; Convex left the id dangling (shown as unknown), here it is nulled.
     */
    categoryId: uuid("category_id"),
    subcategoryId: uuid("subcategory_id"),
    date: day("date").notNull(),
    description: text("description"),
    note: text("note"),
    payee: text("payee"),
    tags: text("tags").array(),

    // Transfer legs only (type = 'transfer').
    /** Receiving account, set on the outgoing leg. Deferred FK. */
    destinationAccountId: uuid("destination_account_id"),
    /** The other leg. Deferred FK: the legs point at each other and are deleted together. */
    linkedTransactionId: uuid("linked_transaction_id"),
    /** Shared by both legs. */
    transferGroupId: uuid("transfer_group_id"),
    createdAt: createdAt(),
  },
  (t) => [
    // Listings and search: newest first by date, then creation order (id breaks ties, for keyset cursors).
    index("transactions_user_id_date_idx").on(t.userId, t.date, t.createdAt, t.id),
    index("transactions_user_id_account_id_date_idx").on(t.userId, t.accountId, t.date, t.createdAt, t.id),
    index("transactions_user_id_category_id_date_idx").on(t.userId, t.categoryId, t.date, t.createdAt, t.id),
    index("transactions_user_id_type_date_idx").on(t.userId, t.type, t.date, t.createdAt, t.id),
    index("transactions_account_id_idx").on(t.accountId),
    index("transactions_category_id_idx").on(t.categoryId),
    index("transactions_transfer_group_id_idx").on(t.transferGroupId),
    // Referencing side of foreign keys, so deletes of the target don't scan.
    index("transactions_subcategory_id_idx").on(t.subcategoryId),
    index("transactions_destination_account_id_idx").on(t.destinationAccountId),
    index("transactions_linked_transaction_id_idx").on(t.linkedTransactionId),
    ownerKey("transactions", t),
    ownedBy("transactions", t.accountId, t, accounts),
    ownedBy("transactions", t.categoryId, t, categories).onDelete("set null"),
    ownedBy("transactions", t.subcategoryId, t, subcategories).onDelete("set null"),
    ownedBy("transactions", t.destinationAccountId, t, accounts),
    ownedBy("transactions", t.linkedTransactionId, t, t),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Savings goals and contributions                                           */
/* -------------------------------------------------------------------------- */

export const savingsGoals = pgTable(
  "savings_goals",
  {
    id: id(),
    userId: userId(),
    name: text("name").notNull(),
    targetAmount: money("target_amount").notNull(),
    /** Tracked amount, updated in place by contributions. */
    currentAmount: money("current_amount").notNull().default(0),
    targetDate: day("target_date"),
    /** Deferred FK. */
    linkedAccountId: uuid("linked_account_id"),
    /** True: virtual tracking. False: contributions move money into the linked account. */
    isVirtual: boolean("is_virtual").notNull(),
    /** Lucide icon name. */
    icon: text("icon"),
    /** Hex color. */
    color: text("color"),
    archived: boolean("archived").notNull().default(false),
    /** Convex `createdAt` (a calendar date, exposed by the API). */
    createdOn: createdOn(),
    createdAt: createdAt(),
  },
  (t) => [
    index("savings_goals_user_id_idx").on(t.userId, t.createdAt),
    index("savings_goals_linked_account_id_idx").on(t.linkedAccountId),
    ownerKey("savings_goals", t),
    ownedBy("savings_goals", t.linkedAccountId, t, accounts),
  ],
);

export const goalContributions = pgTable(
  "goal_contributions",
  {
    id: id(),
    userId: userId(),
    /** Deferred FK. The goal delete removes its contributions first. */
    goalId: uuid("goal_id").notNull(),
    /** Minor units. Positive = deposit, negative = withdrawal. */
    amount: money("amount").notNull(),
    date: day("date").notNull(),
    note: text("note"),
    /**
     * Outgoing transfer leg, for account-linked goals. The transfer can be
     * deleted on its own (transfers page); Convex left the id dangling, here
     * it is nulled.
     */
    transactionId: uuid("transaction_id"),
    createdAt: createdAt(),
  },
  (t) => [
    index("goal_contributions_user_id_idx").on(t.userId, t.createdAt),
    index("goal_contributions_goal_id_idx").on(t.goalId, t.createdAt),
    index("goal_contributions_transaction_id_idx").on(t.transactionId),
    ownedBy("goal_contributions", t.goalId, t, savingsGoals),
    ownedBy("goal_contributions", t.transactionId, t, transactions).onDelete("set null"),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Debts and debt payments                                                   */
/* -------------------------------------------------------------------------- */

export const debts = pgTable(
  "debts",
  {
    id: id(),
    userId: userId(),
    name: text("name").notNull(),
    debtType: debtType("debt_type").notNull(),
    lender: text("lender"),
    originalAmount: money("original_amount").notNull(),
    /** Remaining principal, updated in place by payments. */
    currentBalance: money("current_balance").notNull(),
    /** Annual percentage as entered (e.g. 5.5). A JS number, so double precision. */
    interestRate: doublePrecision("interest_rate"),
    minimumPayment: money("minimum_payment"),
    dueDate: day("due_date"),
    /** Liability account the principal is paid down on. Deferred FK. */
    linkedAccountId: uuid("linked_account_id"),
    archived: boolean("archived").notNull().default(false),
    /** Convex `createdAt` (a calendar date, exposed by the API and used to sort). */
    createdOn: createdOn(),
    createdAt: createdAt(),
  },
  (t) => [
    index("debts_user_id_idx").on(t.userId, t.createdAt),
    index("debts_linked_account_id_idx").on(t.linkedAccountId),
    ownerKey("debts", t),
    ownedBy("debts", t.linkedAccountId, t, accounts),
  ],
);

export const debtPayments = pgTable(
  "debt_payments",
  {
    id: id(),
    userId: userId(),
    /** Deferred FK. The debt delete removes its payments first. */
    debtId: uuid("debt_id").notNull(),
    amount: money("amount").notNull(),
    principalAmount: money("principal_amount").notNull(),
    interestAmount: money("interest_amount").notNull(),
    date: day("date").notNull(),
    note: text("note"),
    /** Deferred FK. Null only on legacy rows (see the header). */
    fromAccountId: uuid("from_account_id"),
    /**
     * Expense on the paying account. Deferred FK: deleted together with the
     * payment. Null only on legacy rows (see the header).
     */
    sourceTransactionId: uuid("source_transaction_id"),
    /** Principal adjustment on the debt's linked account. Deferred FK. */
    liabilityTransactionId: uuid("liability_transaction_id"),
    createdAt: createdAt(),
  },
  (t) => [
    index("debt_payments_user_id_idx").on(t.userId, t.createdAt),
    index("debt_payments_debt_id_idx").on(t.debtId, t.createdAt),
    index("debt_payments_source_transaction_id_idx").on(t.sourceTransactionId),
    index("debt_payments_liability_transaction_id_idx").on(t.liabilityTransactionId),
    index("debt_payments_from_account_id_idx").on(t.fromAccountId),
    ownedBy("debt_payments", t.debtId, t, debts),
    ownedBy("debt_payments", t.fromAccountId, t, accounts),
    ownedBy("debt_payments", t.sourceTransactionId, t, transactions),
    ownedBy("debt_payments", t.liabilityTransactionId, t, transactions),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Finance API idempotency records                                           */
/* -------------------------------------------------------------------------- */

export const apiIdempotencyKeys = pgTable(
  "api_idempotency_keys",
  {
    id: id(),
    userId: userId(),
    /** `Idempotency-Key` header. */
    key: text("key").notNull(),
    /** sha256 of operation + canonical input. */
    requestHash: text("request_hash").notNull(),
    /** Success `data`, replayed for the same key and body. SQL NULL when `data` was null. */
    response: jsonb("response"),
    /** Purged after the TTL. */
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("api_idempotency_keys_user_id_key_key").on(t.userId, t.key),
    index("api_idempotency_keys_created_at_idx").on(t.createdAt),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Chat channel linking                                                      */
/* -------------------------------------------------------------------------- */

/**
 * Single-use codes the web app hands to the user (`/start <code>`). Only the
 * SHA-256 of the code is stored. Purged once expired. Creating a code deletes
 * the user's previous ones for the channel, so there is at most one row per
 * user and channel.
 */
export const channelLinkCodes = pgTable(
  "channel_link_codes",
  {
    id: id(),
    userId: userId(),
    channel: channel("channel").notNull(),
    /** Hex sha256 of the code. */
    codeHash: text("code_hash").notNull(),
    expiresAt: instant("expires_at").notNull(),
    usedAt: instant("used_at"),
    /** When the user ticked consent before creating the code. */
    consentAt: instant("consent_at").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("channel_link_codes_code_hash_key").on(t.codeHash),
    uniqueIndex("channel_link_codes_user_id_channel_key").on(t.userId, t.channel),
    index("channel_link_codes_expires_at_idx").on(t.expiresAt),
  ],
);

/**
 * A linked chat account, active while `unlinked_at` is null. At most one
 * active row per (channel, external_user_id) and per (user_id, channel).
 */
export const channelIdentities = pgTable(
  "channel_identities",
  {
    id: id(),
    userId: userId(),
    channel: channel("channel").notNull(),
    externalUserId: text("external_user_id").notNull(),
    chatId: text("chat_id").notNull(),
    username: text("username"),
    scopes: channelScope("scopes").array().notNull(),
    linkedAt: instant("linked_at").notNull(),
    consentAt: instant("consent_at").notNull(),
    unlinkedAt: instant("unlinked_at"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("channel_identities_active_external_key")
      .on(t.channel, t.externalUserId)
      .where(sql`${t.unlinkedAt} is null`),
    uniqueIndex("channel_identities_active_user_key")
      .on(t.userId, t.channel)
      .where(sql`${t.unlinkedAt} is null`),
    index("channel_identities_user_id_idx").on(t.userId),
    ownerKey("channel_identities", t),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Agent store: state for the chat agent, which keeps none itself            */
/* -------------------------------------------------------------------------- */
/*
 * Ephemeral: never migrated from Convex, deleted by the retention jobs
 * (`src/jobs`), on unlink and on request. Keys between these rows are
 * composite `(x_id, user_id)` like the domain keys, but immediate (not
 * deferred) and `ON DELETE CASCADE`: deleting a session deletes its messages
 * and actions in the same statement.
 */

/**
 * Raw inbound platform events: dedupe before identity resolution, and crash
 * recovery. Hold message text: the payload is emptied once the event is
 * finished and the row is deleted 24h after its last update.
 */
export const agentInboundEvents = pgTable(
  "agent_inbound_events",
  {
    id: id(),
    channel: channel("channel").notNull(),
    /** Platform event id (Telegram `update_id`), unique per channel. */
    eventId: text("event_id").notNull(),
    status: agentEventStatus("status").notNull(),
    /** Bumped each time the event moves to `processing`. */
    attempts: integer("attempts").notNull().default(0),
    /** JSON as sent; "" once done or failed. */
    payload: text("payload").notNull(),
    error: text("error"),
    receivedAt: instant("received_at").notNull(),
    updatedAt: instant("updated_at").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("agent_inbound_events_channel_event_id_key").on(t.channel, t.eventId),
    index("agent_inbound_events_channel_status_updated_at_idx").on(t.channel, t.status, t.updatedAt),
    index("agent_inbound_events_updated_at_idx").on(t.updatedAt),
  ],
);

/** One conversation in one chat, active while `ended_at` is null. */
export const agentSessions = pgTable(
  "agent_sessions",
  {
    id: id(),
    userId: userId(),
    /** The chat identity the session belongs to. Identities are never deleted (only unlinked). */
    identityId: uuid("identity_id").notNull(),
    channel: channel("channel").notNull(),
    chatId: text("chat_id").notNull(),
    startedAt: instant("started_at").notNull(),
    lastActivityAt: instant("last_activity_at").notNull(),
    endedAt: instant("ended_at"),
    /** Denormalized: the per-session cap and the next `seq`. */
    messageCount: integer("message_count").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    index("agent_sessions_active_chat_idx")
      .on(t.userId, t.channel, t.chatId)
      .where(sql`${t.endedAt} is null`),
    index("agent_sessions_user_id_idx").on(t.userId),
    index("agent_sessions_identity_id_idx").on(t.identityId),
    index("agent_sessions_last_activity_at_idx").on(t.lastActivityAt),
    ownerKey("agent_sessions", t),
    foreignKey({
      name: "agent_sessions_identity_id_fk",
      columns: [t.identityId, t.userId],
      foreignColumns: [channelIdentities.id, channelIdentities.userId],
    }),
  ],
);

export const agentMessages = pgTable(
  "agent_messages",
  {
    id: id(),
    userId: userId(),
    sessionId: uuid("session_id").notNull(),
    role: agentMessageRole("role").notNull(),
    /** Provider-agnostic JSON, stored as sent (capped by the contract). */
    content: text("content").notNull(),
    /** 1-based position in the session: the order of record. */
    seq: integer("seq").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("agent_messages_session_id_seq_key").on(t.sessionId, t.seq),
    foreignKey({
      name: "agent_messages_session_id_fk",
      columns: [t.sessionId, t.userId],
      foreignColumns: [agentSessions.id, agentSessions.userId],
    }).onDelete("cascade"),
  ],
);

/** A proposed finance write waiting for the user's Confirm/Cancel. */
export const agentPendingActions = pgTable(
  "agent_pending_actions",
  {
    id: id(),
    userId: userId(),
    sessionId: uuid("session_id").notNull(),
    /** Caller's dedupe key, matched per user and chat identity. */
    clientKey: text("client_key"),
    /** Contract operation name, e.g. "transactions.create". */
    operation: text("operation").notNull(),
    /** JSON, validated against the operation's request schema. */
    input: text("input").notNull(),
    summary: text("summary").notNull(),
    status: agentActionStatus("status").notNull(),
    expiresAt: instant("expires_at").notNull(),
    /** JSON. */
    result: text("result"),
    createdAt: createdAt(),
    updatedAt: instant("updated_at").notNull(),
  },
  (t) => [
    index("agent_pending_actions_session_id_status_idx").on(t.sessionId, t.status),
    index("agent_pending_actions_user_id_client_key_idx").on(t.userId, t.clientKey),
    index("agent_pending_actions_pending_expires_at_idx")
      .on(t.expiresAt)
      .where(sql`${t.status} = 'pending'`),
    index("agent_pending_actions_updated_at_idx").on(t.updatedAt),
    foreignKey({
      name: "agent_pending_actions_session_id_fk",
      columns: [t.sessionId, t.userId],
      foreignColumns: [agentSessions.id, agentSessions.userId],
    }).onDelete("cascade"),
  ],
);
